public class Ex09 {
    static class Config {
        Service service() { return new Service(); }
        Controller controller(Service s) { return new Controller(s); }
    }
    static class Service { String hi() { return "svc"; } }
    static class Controller { private final Service s; Controller(Service s){this.s=s;} String h(){return s.hi();} }
    public static void main(String[] args) {
        // 配置类的方法即“工厂方法”，容器调用它们来产生 bean
        Config cfg = new Config();
        Service s = cfg.service();          // 等价 @Bean
        Controller c = cfg.controller(s);   // 方法参数即依赖
        System.out.println(c.h());
        System.out.println("factory produced: " + (c != null && s != null));
    }
}
